UPDATE b_daily_train
SET status = 1
WHERE ride_date = #{today}
AND status = 0
AND departure_time <= #{now}

UPDATE b_daily_train
SET status = 2
WHERE ride_date = #{today}
AND status < 2
AND arrival_time <= #{now}
AND arrival_time > departure_time

UPDATE b_daily_train
SET status = 2
WHERE ride_date = #{yesterday}
AND status < 2
AND arrival_time <= #{now}
AND arrival_time < departure_time
